## Файл 1. `ReadingHistoryCSV.swift`: сборка CSV-текста

Этот файл не зависит от интерфейса, поэтому его можно положить в общий модуль логики.

```swift
import Foundation

/// Builds a reading history CSV that Excel and Numbers open correctly.
public enum ReadingHistoryCSV {
    public struct Row: Sendable, Equatable {
        public var startedAt: Date
        public var duration: TimeInterval
        public var timeZoneIdentifier: String
        public var bookTitle: String
        public var bookAuthor: String

        public init(
            startedAt: Date,
            duration: TimeInterval,
            timeZoneIdentifier: String,
            bookTitle: String,
            bookAuthor: String
        ) {
            self.startedAt = startedAt
            self.duration = duration
            self.timeZoneIdentifier = timeZoneIdentifier
            self.bookTitle = bookTitle
            self.bookAuthor = bookAuthor
        }
    }

    public enum Delimiter: String, Sendable {
        case comma = ","
        case semicolon = ";"

        /// Excel splits columns by the region's list separator: where the decimal
        /// separator is a comma (Russia, most of Europe), that separator is a semicolon.
        public static func matching(_ locale: Locale) -> Delimiter {
            locale.decimalSeparator == "," ? .semicolon : .comma
        }
    }

    /// UTF-8 with a BOM: without the BOM Excel shows Cyrillic as garbage.
    public static func data(rows: [Row], header: [String], delimiter: Delimiter) -> Data {
        Data(("\u{FEFF}" + text(rows: rows, header: header, delimiter: delimiter)).utf8)
    }

    public static func text(rows: [Row], header: [String], delimiter: Delimiter) -> String {
        var lines = [line(header, delimiter: delimiter)]
        var calendars: [String: Calendar] = [:]

        for row in rows.sorted(by: { $0.startedAt < $1.startedAt }) {
            let calendar = calendars[row.timeZoneIdentifier] ?? {
                var calendar = Calendar(identifier: .gregorian)
                calendar.timeZone = TimeZone(identifier: row.timeZoneIdentifier) ?? .current
                calendars[row.timeZoneIdentifier] = calendar
                return calendar
            }()
            lines.append(line([
                startText(row.startedAt, calendar: calendar),
                String(wholeMinutes(row.duration)),
                row.bookTitle,
                row.bookAuthor,
            ], delimiter: delimiter))
        }
        // RFC 4180 line ending.
        return lines.joined(separator: "\r\n") + "\r\n"
    }

    static func line(_ fields: [String], delimiter: Delimiter) -> String {
        fields.map { field($0, delimiter: delimiter) }.joined(separator: delimiter.rawValue)
    }

    static func field(_ raw: String, delimiter: Delimiter) -> String {
        var value = raw
        // A leading =, +, -, @ makes Excel read the cell as a formula.
        if let first = value.unicodeScalars.first, "=+-@\t\r".unicodeScalars.contains(first) {
            value = "'" + value
        }
        // Check scalars, not Characters: "\r\n" is a single Character in Swift.
        let separator = delimiter.rawValue.unicodeScalars.first!
        let needsQuotes = value.unicodeScalars.contains {
            $0 == separator || $0 == "\"" || $0 == "\n" || $0 == "\r"
        }
        guard needsQuotes else { return value }
        return "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    /// "2026-10-27 22:30" on the clock of the place where the session happened.
    static func startText(_ date: Date, calendar: Calendar) -> String {
        let parts = calendar.dateComponents([.year, .month, .day, .hour, .minute], from: date)
        return "\(pad(parts.year, 4))-\(pad(parts.month, 2))-\(pad(parts.day, 2)) "
            + "\(pad(parts.hour, 2)):\(pad(parts.minute, 2))"
    }

    static func wholeMinutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int(min(duration / 60, 1_000_000_000).rounded())
    }

    private static func pad(_ number: Int?, _ width: Int) -> String {
        let digits = String(number ?? 0)
        return String(repeating: "0", count: max(0, width - digits.count)) + digits
    }
}
```

## Файл 2. `ReadingHistoryExport.swift`: файл для ShareLink

Этот файл в слое приложения.

```swift
import CoreTransferable
import Foundation
import UniformTypeIdentifiers

/// A CSV file of the reading history for ShareLink.
struct ReadingHistoryExport: Transferable, Sendable {
    let rows: [ReadingHistoryCSV.Row]
    let delimiter: ReadingHistoryCSV.Delimiter
    let fileName: String

    init(sessions: [ReadingSession], now: Date = .now, locale: Locale = .current) {
        rows = sessions.map {
            ReadingHistoryCSV.Row(
                startedAt: $0.startedAt,
                duration: $0.duration,
                timeZoneIdentifier: $0.timeZoneIdentifier,
                bookTitle: $0.bookTitle,
                bookAuthor: $0.bookAuthor
            )
        }
        delimiter = .matching(locale)
        let day = now.formatted(Date.ISO8601FormatStyle(timeZone: .current).year().month().day())
        fileName = "reading-history-\(day).csv"
    }

    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { export in
            let header = [
                String(localized: "Начало"),
                String(localized: "Длительность, мин"),
                String(localized: "Название"),
                String(localized: "Автор"),
            ]
            let data = ReadingHistoryCSV.data(rows: export.rows, header: header, delimiter: export.delimiter)
            // A separate folder per export so repeated taps never collide.
            let folder = URL.temporaryDirectory.appending(path: UUID().uuidString, directoryHint: .isDirectory)
            try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            let url = folder.appending(path: export.fileName)
            try data.write(to: url, options: .atomic)
            return SentTransferredFile(url)
        }
    }
}
```

