```swift
import Foundation

/// Одна строка экспорта. Отдельная копия данных, чтобы файл можно было собрать в фоне,
/// даже если ReadingSession — объект базы данных.
public struct ReadingHistoryRow: Sendable, Equatable {
    public var startedAt: Date
    public var duration: TimeInterval
    public var timeZoneIdentifier: String
    public var bookTitle: String
    public var bookAuthor: String

    public init(
        startedAt: Date,
        duration: TimeInterval,
        timeZoneIdentifier: String,
        bookTitle: String,
        bookAuthor: String
    ) {
        self.startedAt = startedAt
        self.duration = duration
        self.timeZoneIdentifier = timeZoneIdentifier
        self.bookTitle = bookTitle
        self.bookAuthor = bookAuthor
    }
}

public enum ReadingHistoryCSV {
    public static let header = ["Начало", "Длительность, мин", "Книга", "Автор"]

    /// Готовый файл: UTF-8 с BOM, строки через CRLF, по одной сессии на строку, от старых к новым.
    public static func make(rows: [ReadingHistoryRow], locale: Locale = .current) -> Data {
        let separator = fieldSeparator(for: locale)
        var formatters: [String: DateFormatter] = [:]

        func startText(_ row: ReadingHistoryRow) -> String {
            if let formatter = formatters[row.timeZoneIdentifier] {
                return formatter.string(from: row.startedAt)
            }
            let formatter = DateFormatter()
            formatter.calendar = Calendar(identifier: .gregorian)
            formatter.locale = Locale(identifier: "en_US_POSIX")
            formatter.timeZone = TimeZone(identifier: row.timeZoneIdentifier) ?? .current
            formatter.dateFormat = "yyyy-MM-dd HH:mm"
            formatters[row.timeZoneIdentifier] = formatter
            return formatter.string(from: row.startedAt)
        }

        var lines = [header.map { escape($0) }.joined(separator: separator)]
        for row in rows.sorted(by: { $0.startedAt < $1.startedAt }) {
            let fields = [
                startText(row),
                String(wholeMinutes(row.duration)),
                escape(neutralizeFormula(row.bookTitle)),
                escape(neutralizeFormula(row.bookAuthor)),
            ]
            lines.append(fields.joined(separator: separator))
        }
        let text = "\u{FEFF}" + lines.joined(separator: "\r\n") + "\r\n"
        return Data(text.utf8)
    }

    /// Excel в русской локали ждёт «;», в английской — «,». Ориентир — десятичный разделитель,
    /// так же решает сам Excel по региональным настройкам.
    static func fieldSeparator(for locale: Locale) -> String {
        locale.decimalSeparator == "," ? ";" : ","
    }

    /// Правила CSV (RFC 4180): поле с запятой, точкой с запятой, кавычкой или переносом строки
    /// берётся в кавычки, а кавычки внутри удваиваются.
    static func escape(_ field: String) -> String {
        let needsQuotes = field.contains { $0 == "," || $0 == ";" || $0 == "\"" || $0 == "\n" || $0 == "\r" }
        guard needsQuotes else { return field }
        return "\"" + field.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    /// Название вроде «=HYPERLINK(...)» Excel выполнил бы как формулу. Апостроф в начале
    /// заставляет показать его как обычный текст.
    static func neutralizeFormula(_ field: String) -> String {
        guard let first = field.first, "=+-@\t\r".contains(first) else { return field }
        return "'" + field
    }

    static func wholeMinutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int((min(duration, 60 * 1_000_000) / 60).rounded())
    }
}
```

